/* ===================== BÀI 3 · Toolchain và profile CPU ===================== */
/* Bài 3 · Toolchain và profile CPU (AMTS-EMB-002-M01-L03, X86-003) — sinh bởi tools/author/mpu8086/l03.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P3=[{"label": "Ví dụ: chương trình .EXE và listing", "code": "; Ví dụ 1: chương trình .EXE (.MODEL SMALL), in OK\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmsg     DB      'OK$'                   ; chuỗi cho INT 21h hàm 09h\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA               ; số hiệu đoạn: bộ nạp điền khi nạp\n        MOV     DS, AX\n        MOV     AH, 09H                 ; in chuỗi DS:DX tới dấu $\n        MOV     DX, OFFSET msg\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Chương trình .EXE chuẩn của khóa. Ở phần Mã máy và chu kỳ, MOV AX, @DATA là B8 12 07: 0712h là số hiệu đoạn dữ liệu do bộ nạp của trình mô phỏng đặt (giả định), trong tệp .OBJ chỗ này để trống cho bộ nạp sửa (Hình 3.2). MOV DX, OFFSET msg là BA 00 00 vì msg ở đầu đoạn dữ liệu. Đoán trước: trước MOV DS, AX, DS bằng bao nhiêu? Đáp án 0700h (đoạn PSP, giả định của trình mô phỏng)."}, {"label": "Ví dụ: cùng chương trình dạng .COM", "code": "; Ví dụ 2: cùng chương trình, dạng .COM (một đoạn)\n        .MODEL  TINY\n        .CODE\n        ORG     100H                    ; .COM bắt đầu ở độ lệch 100h\nMAIN    PROC\n        MOV     AH, 09H                 ; DS = CS = đoạn PSP, không cần nạp\n        MOV     DX, OFFSET msg\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nmsg     DB      'OK$'                   ; dữ liệu nằm chung đoạn với mã\n        END     MAIN\n", "input": "", "note": "Cùng chữ OK nhưng dạng .COM: không có MOV AX, @DATA vì DS = CS = đoạn PSP lúc nạp; IP bắt đầu ở 0100h. msg nằm sau mã ở độ lệch 010Ch nên MOV DX, OFFSET msg là BA 0C 01. Đoán trước: lúc bắt đầu, IP bằng bao nhiêu? Đáp án 0100h."}, {"label": "Lỗi: PUSH số tức thời chỉ có từ 80186", "code": "; Lỗi: PUSH số tức thời chỉ có từ 80186\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        PUSH    5                       ; 8086 không có dạng này\n        POP     BX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: PUSH 5 chỉ có từ 80186. Trình mô phỏng báo đúng dòng và cách viết lại. Sửa: MOV AX, 5 / PUSH AX (Ví dụ 5). Trình dịch thật chỉ báo lỗi khi đã chọn CPU đích 8086."}, {"label": "Lỗi: SHL AX, 4 không phải lệnh 8086", "code": "; Lỗi: dịch nhiều bit bằng số tức thời (80186)\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 5\n        SHL     AX, 4                   ; 8086 chỉ có ...,1 và ...,CL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: SHL AX, 4 (dịch bằng số tức thời lớn hơn 1) chỉ có từ 80186. Sửa: MOV CL, 4 / SHL AX, CL, hoặc 4 lần SHL AX, 1 (Ví dụ 5, bài tập 3)."}, {"label": "Ví dụ: viết lại hai lệnh đó cho 8086", "code": "; Ví dụ 5: viết lại Lỗi 3 và Lỗi 4 cho 8086\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 5                   ; thay PUSH 5: nạp vào thanh ghi\n        PUSH    AX                      ; rồi PUSH thanh ghi\n        POP     BX                      ; BX = 5\n        MOV     CL, 4                   ; thay SHL BX, 4: số lần dịch trong CL\n        SHL     BX, CL                  ; BX = 5 × 16 = 50h\n        MOV     kq, BX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bản 8086 của Lỗi 3 và Lỗi 4. PUSH AX 11 chu kỳ, POP BX 8; SHL BX, CL với CL = 4 tốn 8 + 4 × 4 = 24 chu kỳ. kq = 0050h (5 × 16 = 80). Đoán trước: sau SHL BX, CL, BX bằng bao nhiêu (hệ 16)? Đáp án 0050h."}, {"label": "Bẫy: mã máy 80186 chạy trên CPU 8086", "code": "; Bẫy: byte của lệnh 80186 chạy trên CPU 8086\n        .MODEL  TINY\n        .CODE\n        ORG     100H\nMAIN    PROC\n        MOV     AX, 1\n        DB      0C1H, 0E0H, 03H         ; mã máy của SHL AX, 3 (80186)\n        ADD     AL, '0'                 ; 80186: AX = 8 → in '8'\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: ba byte C1 E0 03 là SHL AX, 3 của 80186 (chèn bằng DB vì trình dịch 8086 không cho viết). Trên 80186 trở lên chương trình in 8. Trên 8088 (theo SingleStepTests, trình mô phỏng làm đúng như vậy) byte C1h chạy như RET: lấy 0000h ở đỉnh ngăn xếp của .COM, nhảy về PSP:0000 gặp INT 20h, chương trình kết thúc mà không in gì, không báo lỗi. Số “16 byte mã” trên bảng lệnh không tính 3 byte viết bằng DB (trình dịch coi DB là dữ liệu); đoạn mã thật trong tệp dài 19 byte. Khi chấm bài, byte DB mà CPU chạy như lệnh được cộng vào số byte mã, nên viết lệnh bằng DB không lách được giới hạn byte. Đoán trước: chương trình có in 8 không? Đáp án không."}, {"label": "Ví dụ: PUSH SP nhận ra CPU họ 8086", "code": "; Ví dụ 7: PUSH SP cho biết CPU thuộc họ 8086/8088\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nhieu    DW      ?                       ; giá trị PUSH SP cất − SP lúc đó\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        PUSH    SP                      ; 8086 cất SP SAU khi đã trừ 2\n        POP     AX                      ; AX = giá trị đã cất, SP trở lại\n        SUB     AX, SP                  ; 8086: −2 (FFFEh); 80286 trở lên: 0\n        MOV     hieu, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "PUSH SP rồi POP AX lấy lại giá trị đã cất; SUB AX, SP so với SP lúc đó. 8086/8088 cất SP sau khi trừ 2 nên hieu = FFFEh (−2); từ 80286 hieu = 0. Đây là một cách cũ để chương trình tự nhận ra CPU họ 8086. Đoán trước: hieu bằng bao nhiêu (hệ 16)? Đáp án FFFEh."}, {"label": "Bẫy: dịch 33 bit theo CL trên 8086", "code": "; Bẫy: dịch 33 bit theo CL, 8086 không cắt số lần dịch\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 1\n        MOV     CL, 33                  ; 8086: dịch đủ 33 lần\n        SHL     AX, CL                  ; 8086: AX = 0; 80286+: 33 AND 31 = 1\n        MOV     kq, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: CL = 33. 8086 dịch đủ 33 lần: bit 1 bị đẩy ra ngoài, AX = 0, lệnh tốn 8 + 4 × 33 = 140 chu kỳ. Từ 80286 (80186 có thể cũng vậy, chưa kiểm) số lần dịch chỉ lấy 5 bit thấp: 33 AND 31 = 1, AX = 2. Cùng mã máy D3 E0, hai CPU cho hai kết quả. Đoán trước: sau SHL AX, CL, AX bằng bao nhiêu trên trình mô phỏng (8086)? Đáp án 0000h."}];
const sim3=makeX86Sim(document.getElementById("x86-l3"),{id:"s3",presets:P3,file:"BAI3.ASM"});
makeX86Ex(document.getElementById("ex-l3"),sim3,[{"t": "Dịch trái 4 bit trên 8086", "d": "Đọc một phím bằng INT 21h hàm 08h. Ghi mã ASCII của phím vào biến phim và byte phim dịch trái 4 bit (bỏ 4 bit cao bị đẩy ra ngoài) vào biến dich. Bản viết cho 80186 dùng SHL AL, 4; hãy viết lại bằng lệnh 8086. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: dịch trái 4 bit trên 8086\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nphim    DB      ?                       ; mã ASCII của phím\ndich    DB      ?                       ; phim dịch trái 4 bit\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím, không hiện\n        INT     21H\n        MOV     phim, AL\n; Bản cho 80186:  SHL AL, 4  (8086 không có)\n; Viết lại bằng lệnh 8086 rồi ghi AL vào dich\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"dosExit": true, "in": "A", "mem": [{"at": "phim", "bytes": [65]}, {"at": "dich", "bytes": [16]}]}, {"dosExit": true, "in": "z", "mem": [{"at": "phim", "bytes": [122]}, {"at": "dich", "bytes": [160]}]}, {"dosExit": true, "in": "1", "mem": [{"at": "phim", "bytes": [49]}, {"at": "dich", "bytes": [16]}]}, {"dosExit": true, "in": " ", "mem": [{"at": "phim", "bytes": [32]}, {"at": "dich", "bytes": [0]}]}, {"dosExit": true, "in": "~", "mem": [{"at": "phim", "bytes": [126]}, {"at": "dich", "bytes": [224]}]}]}, {"t": "Tách hai nửa byte", "d": "Đọc một phím bằng INT 21h hàm 08h. Ghi 4 bit cao của mã ASCII vào biến cao (0–7) và 4 bit thấp vào biến thap (0–15). Ví dụ phím z (7Ah): cao = 7, thap = 0Ah. Chỉ dùng lệnh 8086; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: tách hai nửa byte\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ncao     DB      ?                       ; 4 bit cao của mã phím\nthap    DB      ?                       ; 4 bit thấp của mã phím\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím, không hiện\n        INT     21H\n; Viết code ở đây (chỉ lệnh 8086):\n; cao = AL dịch phải 4 bit, thap = AL AND 0Fh\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"dosExit": true, "in": "z", "mem": [{"at": "cao", "bytes": [7]}, {"at": "thap", "bytes": [10]}]}, {"dosExit": true, "in": "A", "mem": [{"at": "cao", "bytes": [4]}, {"at": "thap", "bytes": [1]}]}, {"dosExit": true, "in": "0", "mem": [{"at": "cao", "bytes": [3]}, {"at": "thap", "bytes": [0]}]}, {"dosExit": true, "in": "~", "mem": [{"at": "cao", "bytes": [7]}, {"at": "thap", "bytes": [14]}]}, {"dosExit": true, "in": " ", "mem": [{"at": "cao", "bytes": [2]}, {"at": "thap", "bytes": [0]}]}, {"dosExit": true, "in": "/", "mem": [{"at": "cao", "bytes": [2]}, {"at": "thap", "bytes": [15]}]}]}, {"t": "Nhân 16 nhanh trên 8086", "d": "Đọc một phím bằng INT 21h hàm 08h và ghi mã ASCII × 16 vào biến word kq (ví dụ phím A: 41h × 16 = 0410h). Code mẫu là bản dịch thẳng của SHL AX, 4 sang 8086 (MOV CL, 4 / SHL AX, CL): đúng nhưng chậm, vì trên 8086 lệnh dịch theo CL tốn 8 + 4 chu kỳ mỗi bit. Viết lại để đạt cả giới hạn chu kỳ và giới hạn byte mã. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: nhân 16 nhanh trên 8086\n; Bản này đúng nhưng chậm: SHL theo CL tốn 8 + 4 chu kỳ\n; mỗi bit. Hãy viết lại phần dịch.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?                       ; mã ASCII × 16\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím\n        INT     21H\n        MOV     AH, 0                   ; AX = mã ASCII\n        MOV     CL, 4\n        SHL     AX, CL                  ; AX = AX × 16\n        MOV     kq, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"dosExit": true, "in": "A", "mem": [{"at": "kq", "bytes": [16, 4]}]}, {"dosExit": true, "in": "0", "mem": [{"at": "kq", "bytes": [0, 3]}]}, {"dosExit": true, "in": "z", "mem": [{"at": "kq", "bytes": [160, 7]}]}, {"dosExit": true, "in": "~", "mem": [{"at": "kq", "bytes": [224, 7]}]}, {"dosExit": true, "in": " ", "mem": [{"at": "kq", "bytes": [0, 2]}]}, {"dosExit": true, "in": "9", "mem": [{"at": "kq", "bytes": [144, 3]}]}], "perf": {"cycles": 145, "bytes": 30}}]);

makeQuiz("quiz3","score3",[{"q": "Trong chuỗi công cụ của chương trình DOS, bước nào tạo ra tệp chạy được .EXE?", "o": ["Trình dịch đọc tệp .ASM và ghi thẳng ra tệp .EXE", "Bộ nạp của DOS đọc tệp .LST rồi ghi ra tệp .EXE", "Trình dịch ngược đọc tệp .OBJ và ghi ra tệp .EXE", "Trình liên kết ghép các tệp .OBJ thành tệp .EXE"], "a": 3, "e": "Trình dịch tạo .OBJ (và .LST nếu yêu cầu); trình liên kết ghép .OBJ thành .EXE/.COM; bộ nạp đưa tệp vào RAM lúc chạy. Một số công cụ (emu8086, ML của MASM) gộp vài bước vào một lệnh nhưng các bước vẫn như vậy."}, {"q": "Trình dịch đặt CPU đích 8086. Dòng nào dịch được?", "o": ["<code>SHL AX, 3<\/code> (dịch 3 bit một lần)", "<code>PUSH 3<\/code> (cất số 3 vào ngăn xếp)", "<code>IMUL AX, BX, 3<\/code> (nhân ba toán hạng)", "<code>SHL AX, CL<\/code> (sau <code>MOV CL, 3<\/code>)"], "a": 3, "e": "8086 chỉ dịch 1 bit hoặc CL bit. SHL AX, 3, PUSH 3 và IMUL ba toán hạng có từ 80186."}, {"q": "Chương trình .COM vừa được DOS nạp, chưa chạy lệnh nào. Phát biểu nào đúng?", "o": ["CS = đoạn mã, DS = @DATA và IP = 0000h", "DS = ES = đoạn PSP, CS theo phần đầu tệp", "CS = DS = ES = SS = đoạn PSP và IP = 0100h", "CS = DS = 0000h và IP = 0100h như mọi tệp"], "a": 2, "e": ".COM là ảnh bộ nhớ thô của một đoạn: DOS nạp sau PSP 256 byte, đặt mọi thanh ghi đoạn bằng đoạn PSP và IP = 0100h. DS = PSP, CS theo phần đầu là cách nạp .EXE."}, {"q": "Đoạn sau chạy trên 8086. AX bằng bao nhiêu sau lệnh cuối?<pre class=\"mp-asm\">        MOV     AX, 1\n        MOV     CL, 33\n        SHL     AX, CL<\/pre>", "o": ["0002h: CPU chỉ lấy 5 bit thấp của CL là 1", "0000h: 8086 dịch đủ 33 lần nên bit 1 ra ngoài", "8000h: dịch 33 lần quay vòng về bit cao nhất", "Lỗi dịch: số lần dịch phải nhỏ hơn 16 bit"], "a": 1, "e": "8086 không cắt số lần dịch (Ví dụ 8). Cắt còn 5 bit (33 → 1, AX = 2) là cách của các CPU đời sau 8086 (chắc chắn từ 80286). SHL không quay vòng, và CL = 33 vẫn dịch được."}, {"q": "MASM dịch <code>MOV AX, BX<\/code> thành <code>8B C3<\/code>, NASM thành <code>89 D8<\/code>. Phát biểu nào đúng?", "o": ["Một trong hai trình dịch sinh sai mã máy cho 8086", "89 D8 chép AX vào BX, ngược với lệnh đã viết", "Hai cách mã hóa hợp lệ của cùng một lệnh, cùng 2 byte", "8B C3 là lệnh 80186 nên không chạy được trên 8086"], "a": 2, "e": "Lệnh MOV giữa hai thanh ghi có bit d chọn toán hạng nào nằm ở trường reg: 8B (d = 1) với C3 và 89 (d = 0) với D8 đều là MOV AX, BX. Dài bằng nhau, chạy như nhau."}]);

